    let root = serde_json::to_value(schemars::schema_for!(ConfigSchemaState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "config",
        "1.0.0",
        "Global key/value config store",
        &root,
